import pandas as pd
import numpy as np

# Load the transport energy use data and borough adjacency list into pandas DataFrames
transport_data = pd.read_csv('chunks_csv/moran_local_2022_transport.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute neighborhood transport energy use averages
neighborhood_averages = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if neighbor not in neighborhood_averages:
        neighborhood_averages[neighbor] = []
    neighborhood_averages[neighbor].append(transport_data.loc[transport_data['borough'] == neighbor, 'Transport_value'].values[0])

neighborhood_averages = {k: np.mean(v) for k, v in neighborhood_averages.items()}

# Classify boroughs as HOT SPOT or COLD SPOT
classifications = {}
for index, row in transport_data.iterrows():
    borough = row['borough']
    if borough not in classifications:
        classifications[borough] = {}
    classifications[borough]['transport_value'] = row['Transport_value']
    classifications[borough]['neighborhood_average'] = neighborhood_averages.get(borough, 0)
    if row['Transport_value'] > neighborhood_averages.get(borough, 0):
        classifications[borough]['classification'] = 'HOT SPOT'
    elif row['Transport_value'] < neighborhood_averages.get(borough, 0):
        classifications[borough]['classification'] = 'COLD SPOT'
    else:
        classifications[borough]['classification'] = 'NEUTRAL'

# Compute statistical significance
def permutation_test(data, n_permutations=500):
    test_statistic = data['transport_value'] - data['neighborhood_average']
    permutation_distributions = []
    for _ in range(n_permutations):
        permutation_distribution = np.random.permutation(test_statistic)
        permutation_distributions.append(permutation_distribution)
    permutation_distributions = np.array(permutation_distributions)
    p_value = np.mean(np.abs(permutation_distributions) > np.abs(test_statistic))
    return p_value

# Identify qualifying boroughs
qualifying_boroughs = []
for borough, classification in classifications.items():
    if classification['classification'] in ['HOT SPOT', 'COLD SPOT']:
        data_points_used = transport_data[transport_data['borough'] == borough].shape[0]
        p_value = permutation_test(classifications[borough])
        qualifying_boroughs.append((borough, classification['classification'], p_value))

# Format the final answer
final_answer = []
for borough, classification, p_value in qualifying_boroughs:
    final_answer.append(f'{borough} ({classification}, statistical method={p_value})')

# Print the final answer
print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {", ".join(final_answer)}')
